#!/usr/bin/env python3
"""Install server-side Evan Skill.wz metadata used by EverLeaf.

The user-supplied Evan data pack provides 42 of the 43 Evan skill records used
by the server. Jump Down (20011006) is absent from that pack, so this transform
copies the equivalent Cygnus beginner Jump Down record (10001006) and renames
it for Evan. Client-only canvas/sound payloads are intentionally excluded.
"""
from __future__ import annotations

import base64
import copy
import gzip
import json
from pathlib import Path
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
SKILL_WZ = ROOT / "wz" / "Skill.wz"
EXPECTED = {
    20010012, 20011000, 20011001, 20011002, 20011003, 20011004,
    20011005, 20011006, 20011007, 20011009, 20011010, 20011011,
    22000000, 22001001, 22101000, 22101001, 22111000, 22111001,
    22121000, 22121001, 22131000, 22131001, 22140000, 22141001,
    22141002, 22141003, 22150000, 22151001, 22151002, 22151003,
    22160000, 22161001, 22161002, 22161003, 22170001, 22171000,
    22171002, 22171003, 22171004, 22181000, 22181001, 22181002,
    22181003,
}
PAYLOAD = ""


def _skill_node(root: ET.Element) -> ET.Element:
    node = next((child for child in root if child.attrib.get("name") == "skill"), None)
    if node is None:
        raise SystemExit("Skill.wz XML has no skill directory")
    return node


def _ids(xml_text: str) -> set[int]:
    root = ET.fromstring(xml_text)
    return {
        int(node.attrib["name"])
        for node in _skill_node(root)
        if node.tag == "imgdir" and node.attrib.get("name", "").isdigit()
    }


def _jump_down() -> ET.Element:
    source = ET.parse(SKILL_WZ / "1000.img.xml").getroot()
    for node in _skill_node(source):
        if node.attrib.get("name") == "10001006":
            clone = copy.deepcopy(node)
            clone.set("name", "20011006")
            return clone
    raise SystemExit("Unable to source beginner Jump Down skill 10001006")


def main() -> None:
    raw = gzip.decompress(base64.b64decode(PAYLOAD))
    files: dict[str, str] = json.loads(raw.decode("utf-8"))
    SKILL_WZ.mkdir(parents=True, exist_ok=True)

    root_2001 = ET.fromstring(files["2001.img.xml"])
    _skill_node(root_2001).append(_jump_down())
    ET.indent(root_2001, space="    ")
    files["2001.img.xml"] = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        + ET.tostring(root_2001, encoding="unicode")
        + "\n"
    )

    discovered: set[int] = set()
    for filename, xml_text in sorted(files.items()):
        ids = _ids(xml_text)
        discovered.update(ids)
        (SKILL_WZ / filename).write_text(xml_text, encoding="utf-8")
        print(f"evan_skill_data={filename} skills={len(ids)}")

    missing = EXPECTED - discovered
    unexpected = discovered - EXPECTED
    if missing or unexpected:
        raise SystemExit(
            f"Evan skill payload mismatch: missing={sorted(missing)} unexpected={sorted(unexpected)}"
        )
    print(f"evan_skill_count={len(discovered)}")
    print("evan_skill_data=ready")


if __name__ == "__main__":
    main()
